/* From Uiverse.io by kennyotsu - Tags: complex, 3d, card */
/*works janky on mobile :<*/
.__UIV_SCOPE__ .container {
  position: relative;
  width: 190px;
  height: 254px;
  transition: 200ms;
}

.__UIV_SCOPE__ .container:active {
  width: 180px;
  height: 245px;
}

.__UIV_SCOPE__ #card {
  position: absolute;
  inset: 0;
  z-index: 0;
  display: flex;
  justify-content: center;
  align-items: center;
  border-radius: 20px;
  transition: 700ms;
  background: linear-gradient(43deg, rgb(65, 88, 208) 0%, rgb(200, 80, 192) 46%, rgb(255, 204, 112) 100%);
}

.__UIV_SCOPE__ .subtitle {
  transform: translateY(160px);
  color: rgb(134, 110, 221);
  text-align: center;
  width: 100%;
}

.__UIV_SCOPE__ .title {
  opacity: 0;
  transition-duration: 300ms;
  transition-timing-function: ease-in-out-out;
  transition-delay: 100ms;
  position: absolute;
  font-size: x-large;
  font-weight: bold;
  color: white;
}

.__UIV_SCOPE__ .tracker:hover ~ #card .title {
  opacity: 1;
}

.__UIV_SCOPE__ #prompt {
  bottom: 8px;
  left: 12px;
  z-index: 20;
  font-size: 20px;
  font-weight: bold;
  transition: 300ms ease-in-out-out;
  position: absolute;
  max-width: 110px;
  color: rgb(255, 255, 255);
}

.__UIV_SCOPE__ .tracker {
  position: absolute;
  z-index: 200;
  width: 100%;
  height: 100%;
}

.__UIV_SCOPE__ .tracker:hover {
  cursor: pointer;
}

.__UIV_SCOPE__ .tracker:hover ~ #card #prompt {
  opacity: 0;
}

.__UIV_SCOPE__ .tracker:hover ~ #card {
  transition: 300ms;
  filter: brightness(1.1);
}

.__UIV_SCOPE__ .container:hover #card::before {
  transition: 200ms;
  content: '';
  opacity: 80%;
}

.__UIV_SCOPE__ .canvas {
  perspective: 800px;
  inset: 0;
  z-index: 200;
  position: absolute;
  display: grid;
  grid-template-columns: 1fr 1fr 1fr 1fr 1fr;
  grid-template-rows: 1fr 1fr 1fr 1fr 1fr;
  gap: 0px 0px;
  grid-template-areas: "tr-1 tr-2 tr-3 tr-4 tr-5"
    "tr-6 tr-7 tr-8 tr-9 tr-10"
    "tr-11 tr-12 tr-13 tr-14 tr-15"
    "tr-16 tr-17 tr-18 tr-19 tr-20"
    "tr-21 tr-22 tr-23 tr-24 tr-25";
}

.__UIV_SCOPE__ #card::before {
  content: '';
  background: linear-gradient(43deg, rgb(65, 88, 208) 0%, rgb(200, 80, 192) 46%, rgb(255, 204, 112) 100%);
  filter: blur(2rem);
  opacity: 30%;
  width: 100%;
  height: 100%;
  position: absolute;
  z-index: -1;
  transition: 200ms;
}

